import com.intellij.openapi.fileEditor.FileEditor;
import com.intellij.openapi.fileEditor.TextEditor;
import com.intellij.openapi.util.Couple;
import com.intellij.psi.PsiElement;
import com.intellij.psi.PsiFile;
import com.intellij.psi.tree.IElementType;
import com.intellij.psi.util.PsiTreeUtil;
import org.asciidoc.intellij.AsciiDocLanguage;
import org.asciidoc.intellij.ui.SplitFileEditor;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

public class AsciiDocActionUtil {
  @Nullable
  public static SplitFileEditor<?, ?> findSplitEditor(AnActionEvent e) {
    final FileEditor editor = e.getData(PlatformDataKeys.FILE_EDITOR);
    if (editor instanceof SplitFileEditor) {
      return (SplitFileEditor<?, ?>) editor;
    } else {
      return SplitFileEditor.PARENT_SPLIT_KEY.get(editor);
    }
  }

  @Nullable
  public static Editor findAsciiDocTextEditor(AnActionEvent e) {
    final SplitFileEditor<?, ?> splitEditor = findSplitEditor(e);
    if (splitEditor == null) {
      // This fallback is used primarily for testing

      final PsiFile psiFile = e.getData(CommonDataKeys.PSI_FILE);
      if (psiFile != null && psiFile.getLanguage() == AsciiDocLanguage.INSTANCE && ApplicationManager.getApplication().isUnitTestMode()) {
        return e.getData(CommonDataKeys.EDITOR);
      } else {
        return null;
      }
    }

    final TextEditor mainEditor = splitEditor.getMainEditor();
    if (!mainEditor.getComponent().isVisible()) {
      return null;
    }

    return mainEditor.getEditor();
  }

  @Nullable
  public static Couple<PsiElement> getElementsUnderCaretOrSelection(@NotNull PsiFile file, @NotNull Caret caret) {
    if (caret.getSelectionStart() == caret.getSelectionEnd()) {
      final PsiElement element = file.findElementAt(caret.getSelectionStart());
      if (element == null) {
        return null;
      }
      return Couple.of(element, element);
    } else {
      final PsiElement startElement = file.findElementAt(caret.getSelectionStart());
      final PsiElement endElement = file.findElementAt(caret.getSelectionEnd());
      if (startElement == null || endElement == null) {
        return null;
      }
      return Couple.of(startElement, endElement);
    }
  }

  @Nullable
  public static PsiElement getCommonParentOfType(@NotNull PsiElement element1,
                                                 @NotNull PsiElement element2,
                                                 @NotNull final IElementType elementType) {
    final PsiElement base = PsiTreeUtil.findCommonParent(element1, element2);
    return PsiTreeUtil.findFirstParent(base, false, element -> {
      final ASTNode node = element.getNode();
      return node != null && node.getElementType() == elementType;
    });
  }
}

package org.asciidoc.intellij.actions;

import com.intellij.openapi.actionSystem.AnActionEvent;
import org.asciidoc.intellij.actions.asciidoc.AsciiDocAction;
import org.asciidoc.intellij.editor.AsciiDocHtmlPanel;
import org.asciidoc.intellij.editor.AsciiDocSplitEditor;
import org.asciidoc.intellij.editor.jcef.AsciiDocJCEFHtmlPanel;
import org.asciidoc.intellij.ui.SplitFileEditor;
import org.jetbrains.annotations.NotNull;

public class OpenDevtoolsAction extends AsciiDocAction {
  @Override
  public void actionPerformed(@NotNull AnActionEvent event) {
    SplitFileEditor<?, ?> fileEditor = AsciiDocActionUtil.findSplitEditor(event);
    if (fileEditor instanceof AsciiDocSplitEditor asciiDocSplitEditor) {
      AsciiDocHtmlPanel panel = asciiDocSplitEditor.getSecondEditor().getPanel();
      if (panel instanceof AsciiDocJCEFHtmlPanel asciiDocJCEFHtmlPanel) {
        if (!asciiDocJCEFHtmlPanel.isDisposed()) {
          asciiDocJCEFHtmlPanel.openDevtools();
        }
      }
    }
  }

  @Override
  public void update(@NotNull AnActionEvent event) {
    boolean visible = false;
    SplitFileEditor<?, ?> fileEditor = AsciiDocActionUtil.findSplitEditor(event);
    if (fileEditor instanceof AsciiDocSplitEditor asciiDocSplitEditor) {
      AsciiDocHtmlPanel panel = asciiDocSplitEditor.getSecondEditor().getPanel();
      if (panel instanceof AsciiDocJCEFHtmlPanel) {
        visible = true;
      }
    }
    event.getPresentation().setVisible(visible);
  }
}

package org.asciidoc.intellij.actions;

import com.intellij.codeInsight.AutoPopupController;
import com.intellij.codeInsight.editorActions.TypedHandlerDelegate;
import com.intellij.openapi.editor.Editor;
import com.intellij.openapi.project.Project;
import com.intellij.psi.PsiFile;
import org.asciidoc.intellij.file.AsciiDocFileType;
import org.jetbrains.annotations.NotNull;

/**
 * Show the autocomplete lookup list automatically in places where it could be helpful to the user.
 */
public class AsciiDocTriggerAutoCompleteTypedHandler extends TypedHandlerDelegate {

  @Override
  public @NotNull Result charTyped(char charTyped, @NotNull Project project, @NotNull Editor editor, @NotNull PsiFile file) {
    if (file.getFileType().equals(AsciiDocFileType.INSTANCE)) {
      // will not see single quotes (') and double quotes (") as they will be handled by the quote handler
      if (charTyped == ':' // might be the start of an attribute declaration: ':attribute:', or the body of a macro: 'xref:file.adoc[]`
        || charTyped == '!' // might be the start of an attribute unset like ':!attribute:'
        || charTyped == '{' // might be the start of an attribute reference: '{attribute}'
        || charTyped == '<' // might be the start of an anchor reference: '<<anchor>>'
        || charTyped == '#' // might be the start of an anchor in an xref: 'xref:file.adoc#anchor[]'
        || charTyped == '=' // might be the start of a tag like 'include::file.adoc[tag=name]'
        || charTyped == ',' // might be the start of a language like '[source,java]'
      ) {
        // for now, always try to show the lookup. The condition could try to be more specific in the future.
        AutoPopupController.getInstance(project).autoPopupMemberLookup(editor, null);
      }
    }
    return Result.CONTINUE;
  }
}
